//! Writes the generated files of the shared `reference/` folder from the
//! registry of each ready synth and from the music dictionary.
//!
//! Each synth gets one catalogue file per layer and one `global` file
//! under `reference/<synth>/`. A control with several
//! instances is one row, and the registry never leaves this crate as a
//! whole table: the files hold one row per pattern.

use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::fs;
use std::path::{Path, PathBuf};

use sound_to_patch::preset::catalogue::{Layer, placement, unread_keys};
use sound_to_patch::preset::registry::{
    Law, ParamKind, ParamSpec, Physical, Provenance, UnitLaw, registry_for,
};
use sound_to_patch::synth::Synth;

/// The shared reference folder, relative to the repository root. The
/// plugin and the project skill read it through links.
pub(crate) const REFERENCE: &str = "reference";

/// Files above this many lines open with a table of contents.
pub(crate) const CONTENTS_ABOVE: usize = 100;

/// The section that collects groups with one control each.
const OTHER: &str = "other";

/// The first line of every generated file.
pub(crate) const HEADER: &str = "<!-- Generated by `cargo xtask reference`. Do not edit. -->";

/// The hand-written part of each Vital layer file, merged above its rows.
/// The source sits in `dictionary/vital/`; edit it there.
const VITAL_TEXT: [(Layer, &str); 8] = [
    (
        Layer::Pitch,
        include_str!("../../dictionary/vital/pitch.md"),
    ),
    (
        Layer::Oscillator,
        include_str!("../../dictionary/vital/oscillator.md"),
    ),
    (
        Layer::Unison,
        include_str!("../../dictionary/vital/unison.md"),
    ),
    (
        Layer::Filter,
        include_str!("../../dictionary/vital/filter.md"),
    ),
    (
        Layer::Envelope,
        include_str!("../../dictionary/vital/envelope.md"),
    ),
    (
        Layer::Modulation,
        include_str!("../../dictionary/vital/modulation.md"),
    ),
    (
        Layer::Distortion,
        include_str!("../../dictionary/vital/distortion.md"),
    ),
    (
        Layer::Space,
        include_str!("../../dictionary/vital/space.md"),
    ),
];

/// The fields every entry of a hand-written part holds.
const FIELDS: [&str; 3] = ["Keys", "Effect", "Words"];

/// The hand-written part of a layer file, if the synth has one.
fn written(synth: Synth, layer: Layer) -> Option<&'static str> {
    match synth {
        Synth::Vital => VITAL_TEXT
            .iter()
            .find(|(of, _)| *of == layer)
            .map(|(_, text)| *text),
        Synth::Serum2 => None,
    }
}

/// One entry of a hand-written part: a `###` heading and its fields.
#[derive(Debug)]
struct Entry {
    heading: String,
    keys: Vec<String>,
    fields: Vec<String>,
}

/// The entries of a hand-written part. A field is a line `- Name: text`.
fn entries(text: &str) -> Vec<Entry> {
    let mut entries: Vec<Entry> = Vec::new();
    // A field belongs to the entry above it until another heading starts.
    let mut open = false;
    for line in text.lines() {
        if let Some(heading) = line.strip_prefix("### ") {
            entries.push(Entry {
                heading: heading.to_owned(),
                keys: Vec::new(),
                fields: Vec::new(),
            });
            open = true;
        } else if line.starts_with('#') {
            open = false;
        } else if let (true, Some(entry), Some((name, value))) = (
            open,
            entries.last_mut(),
            line.strip_prefix("- ")
                .and_then(|field| field.split_once(": ")),
        ) {
            if value.trim().is_empty() {
                continue;
            }
            if name == "Keys" {
                entry
                    .keys
                    .extend(value.split('`').skip(1).step_by(2).map(ToOwned::to_owned));
            }
            entry.fields.push(name.to_owned());
        }
    }
    entries
}

/// The problems of a hand-written part: an entry without a field, a key
/// that is no pattern of the layer, and a layer pattern no entry names.
fn text_problems(layer: Layer, text: &str, patterns: &[&str]) -> Vec<String> {
    let mut problems = Vec::new();
    let mut named = Vec::new();
    for entry in entries(text) {
        for field in FIELDS {
            if !entry.fields.iter().any(|have| have == field) {
                problems.push(format!(
                    "{layer}: entry {:?} lacks the field {field}",
                    entry.heading
                ));
            }
        }
        for key in &entry.keys {
            if !patterns.contains(&key.as_str()) {
                problems.push(format!(
                    "{layer}: entry {:?} names `{key}`, which is no key pattern of this layer",
                    entry.heading
                ));
            }
            named.push(key.clone());
        }
    }
    for pattern in patterns {
        if !named.iter().any(|key| key == pattern) {
            problems.push(format!("{layer}: no entry names `{pattern}`"));
        }
    }
    problems
}

/// Writes the generated files, or with `check` fails when one differs.
pub(crate) fn run(root: &Path, check: bool) -> crate::Result<()> {
    let files = generate()?;
    crate::music::check_coverage()?;
    let mut stale = Vec::new();
    for (relative, text) in &files {
        let path = root.join(relative);
        if check {
            if fs::read_to_string(&path).ok().as_deref() != Some(text.as_str()) {
                stale.push(relative.display().to_string());
            }
        } else {
            if let Some(dir) = path.parent() {
                fs::create_dir_all(dir)?;
            }
            fs::write(&path, text)?;
        }
    }
    let folders = Synth::READY
        .iter()
        .map(|synth| synth.as_str())
        .chain([crate::music::CORE]);
    for folder in folders {
        let dir = root.join(REFERENCE).join(folder);
        for entry in fs::read_dir(&dir).into_iter().flatten() {
            let entry = entry?;
            if entry.file_type()?.is_dir() {
                continue;
            }
            let path = entry.path();
            let relative = path.strip_prefix(root)?.to_owned();
            if !files.contains_key(&relative) {
                stale.push(format!("{} (not generated; delete it)", relative.display()));
            }
        }
    }
    if stale.is_empty() {
        Ok(())
    } else {
        Err(format!(
            "these reference files differ from the generator: {}. Run `cargo xtask reference`",
            stale.join(", ")
        )
        .into())
    }
}

/// Every generated file, by path relative to the repository root.
pub(crate) fn generate() -> crate::Result<BTreeMap<PathBuf, String>> {
    let mut files = BTreeMap::new();
    for synth in Synth::READY {
        let dir = Path::new(REFERENCE).join(synth.as_str());
        let catalogue = Catalogue::of(synth)?;
        let mut problems = Vec::new();
        for layer in Layer::ALL {
            let text = written(synth, layer);
            if let Some(text) = text {
                problems.extend(text_problems(layer, text, &catalogue.patterns(layer)));
            }
            files.insert(
                dir.join(format!("{layer}.md")),
                catalogue.layer_file(Some(layer), text),
            );
        }
        if !problems.is_empty() {
            return Err(format!(
                "the hand-written text in dictionary/{synth}/ needs fixing:\n{}",
                problems.join("\n")
            )
            .into());
        }
        files.insert(dir.join("global.md"), catalogue.layer_file(None, None));
    }
    files.extend(crate::music::files()?);
    files.extend(crate::words::files()?);
    Ok(files)
}

/// One row: the instances of a pattern that share a tag.
#[derive(Debug)]
struct Row {
    label: String,
    pattern: String,
    instances: Vec<String>,
    specs: Vec<ParamSpec>,
}

/// The rows of one synth by layer, and the keys outside the rows.
#[derive(Debug)]
struct Catalogue {
    synth: Synth,
    rows: BTreeMap<Option<Layer>, Vec<Row>>,
    legacy: Vec<String>,
    unread: Vec<String>,
}

impl Catalogue {
    fn of(synth: Synth) -> crate::Result<Self> {
        let registry = registry_for(synth)?;
        let mut rows: BTreeMap<Option<Layer>, Vec<Row>> = BTreeMap::new();
        let mut legacy = Vec::new();
        for spec in registry.iter() {
            let place = placement(synth, &spec.key)?;
            if spec.legacy {
                legacy.push(spec.key.clone());
                continue;
            }
            let layer_rows = rows.entry(place.layer).or_default();
            let tag = tag(spec);
            if let Some(row) = layer_rows
                .iter_mut()
                .find(|row| row.pattern == place.pattern && tag == self::tag(&row.specs[0]))
            {
                row.instances.extend(place.instance);
                row.specs.push(spec.clone());
            } else {
                let label = match &place.instance {
                    Some(id) => spec
                        .label
                        .replacen(&format!(" {} ", id.to_uppercase()), " N ", 1),
                    None => spec.label.clone(),
                };
                layer_rows.push(Row {
                    label,
                    pattern: place.pattern,
                    instances: place.instance.into_iter().collect(),
                    specs: vec![spec.clone()],
                });
            }
        }
        for layer_rows in rows.values_mut() {
            for row in layer_rows.iter_mut() {
                sort_instances(row);
            }
            layer_rows.sort_by(|a, b| {
                (&a.pattern, tag(&a.specs[0])).cmp(&(&b.pattern, tag(&b.specs[0])))
            });
        }
        let mut unread: Vec<String> = unread_keys(synth)?
            .iter()
            .map(|key| {
                placement(synth, key).map_or_else(|_| (*key).to_owned(), |place| place.pattern)
            })
            .collect();
        unread.dedup();
        Ok(Self {
            synth,
            rows,
            legacy,
            unread,
        })
    }

    /// The key patterns of a layer, once each.
    fn patterns(&self, layer: Layer) -> Vec<&str> {
        let mut patterns: Vec<&str> = self
            .rows
            .get(&Some(layer))
            .into_iter()
            .flatten()
            .map(|row| row.pattern.as_str())
            .collect();
        patterns.dedup();
        patterns
    }

    /// A layer file: the title, the hand-written `text` if any, then the
    /// rows by section.
    fn layer_file(&self, layer: Option<Layer>, written: Option<&str>) -> String {
        let name = self.synth.name();
        let title = layer.map_or("Controls outside the layers", Layer::title);
        let empty = Vec::new();
        let rows = self.rows.get(&layer).unwrap_or(&empty);
        let mut sections: BTreeMap<String, Vec<&Row>> = BTreeMap::new();
        for row in rows {
            sections.entry(family(&row.pattern)).or_default().push(row);
        }
        let singles: Vec<String> = sections
            .iter()
            .filter(|(_, rows)| rows.len() == 1)
            .map(|(family, _)| family.clone())
            .collect();
        if singles.len() > 1 {
            for family in singles {
                if let Some(rows) = sections.remove(&family) {
                    sections.entry(OTHER.to_owned()).or_default().extend(rows);
                }
            }
        }

        let mut body = String::new();
        for (family, rows) in &sections {
            let _ = writeln!(body, "\n## {}\n", heading(family, rows));
            body.push_str(
                "| Control | Key | Instances | Unit | Range | Default | Tag | Verified on | Tuning note |\n",
            );
            body.push_str("| :-- | :-- | :-- | :-- | :-- | :-- | :-- | :-- | :-- |\n");
            for row in rows {
                body.push_str(&row_line(row));
            }
        }
        if layer.is_none() {
            body.push_str("\n## Legacy keys\n\nReaders accept these keys and writers refuse them. Never write one.\n\n");
            for key in &self.legacy {
                let _ = writeln!(body, "- `{key}`");
            }
            body.push_str("\n## Keys of newer builds\n\nFiles saved by newer builds of the app hold these keys. The registry has no range for them, and a rewrite keeps them as they are.\n\n");
            for key in &self.unread {
                let _ = writeln!(body, "- `{key}`");
            }
        }

        let mut text = format!(
            "{HEADER}\n\n# {name}: {title}\n\n\
             One row per control. In a key, `N` stands for each number listed under Instances. \
             Ranges and defaults are in the unit of the control; where it has no unit, they are stored values.\n\n\
             Tags: `from facts` is read from a source we may use; `measured` is confirmed in the app or in a render; \
             `uncalibrated` is an estimate, so tune it by ear with its tuning note. \
             Verified on names the build that confirmed the key and its default.\n"
        );
        if written.is_some() {
            text.push_str(
                "\nEach entry of the written part names its keys. The rows of those keys below hold \
                 the on-screen label, unit, range, default, tag, verified build and tuning note.\n",
            );
        }
        let written_headings: Vec<&str> = written
            .into_iter()
            .flat_map(str::lines)
            .filter_map(|line| line.strip_prefix("## "))
            .collect();
        let lines = text.lines().count()
            + body.lines().count()
            + written.map_or(0, |written| written.lines().count());
        if written.is_some() || (lines > CONTENTS_ABOVE && sections.len() > 1) {
            text.push_str("\n## Contents\n\n");
            for heading in &written_headings {
                let _ = writeln!(text, "- [{heading}](#{})", anchor(heading));
            }
            for (family, rows) in &sections {
                let heading = heading(family, rows);
                let _ = writeln!(text, "- [{heading}](#{})", anchor(&heading));
            }
            if layer.is_none() {
                text.push_str("- [Legacy keys](#legacy-keys)\n- [Keys of newer builds](#keys-of-newer-builds)\n");
            }
        }
        if let Some(written) = written {
            text.push('\n');
            text.push_str(written.trim_end());
            text.push('\n');
        }
        text.push_str(&body);
        text
    }
}

/// The tag of an entry: one word set per row.
fn tag(spec: &ParamSpec) -> &'static str {
    match spec.provenance {
        Provenance::FromFacts => "from facts",
        Provenance::Measured => "measured",
        Provenance::Interim => "uncalibrated",
    }
}

/// The section of a pattern: its group, such as `osc_N` or `chorus`.
fn family(pattern: &str) -> String {
    match pattern.split_once("_N_") {
        Some((group, _)) => format!("{group}_N"),
        None => pattern.split('_').next().unwrap_or(pattern).to_owned(),
    }
}

/// The heading of a section: the words its labels share, else the group
/// in code, or the other controls.
fn heading(family: &str, rows: &[&Row]) -> String {
    if family == OTHER {
        return "Other controls".to_owned();
    }
    // The words every label of the section starts with, such as `Filter FX`.
    let mut common: Vec<&str> = rows[0].label.split(' ').collect();
    for row in &rows[1..] {
        let words: Vec<&str> = row.label.split(' ').collect();
        let shared = common
            .iter()
            .zip(&words)
            .take_while(|(a, b)| a == b)
            .count();
        common.truncate(shared);
    }
    if common.is_empty() {
        format!("`{family}`")
    } else {
        common.join(" ")
    }
}

/// The heading anchor mdBook and GitHub give a code heading.
pub(crate) fn anchor(heading: &str) -> String {
    heading
        .to_lowercase()
        .chars()
        .filter(|c| c.is_alphanumeric() || matches!(c, '_' | '-' | ' '))
        .collect::<String>()
        .replace(' ', "-")
}

fn row_line(row: &Row) -> String {
    let first = &row.specs[0];
    let unit = first.unit().map_or("none", |unit| unit.type_name());
    let instances = if row.instances.is_empty() {
        "-".to_owned()
    } else {
        row.instances.join(", ")
    };
    let verified = first
        .verified_on
        .as_ref()
        .map_or_else(|| "unverified".to_owned(), ToString::to_string);
    let cells = [
        row.label.clone(),
        format!("`{}`", row.pattern),
        instances,
        unit.to_owned(),
        range(first),
        defaults(row),
        tag(first).to_owned(),
        verified,
        first.tuning_note.clone().unwrap_or_default(),
    ];
    let cells: Vec<String> = cells.iter().map(|cell| cell.replace('|', "\\|")).collect();
    format!("| {} |\n", cells.join(" | "))
}

/// Sorts the instances of a row by number, keeping each with its entry.
/// The registry sorts keys as text, so `10` comes before `2` there.
fn sort_instances(row: &mut Row) {
    if row.instances.len() != row.specs.len() {
        return;
    }
    let mut pairs: Vec<(String, ParamSpec)> =
        row.instances.drain(..).zip(row.specs.drain(..)).collect();
    pairs.sort_by_key(|(id, _)| (id.len(), id.clone()));
    (row.instances, row.specs) = pairs.into_iter().unzip();
}

fn range(spec: &ParamSpec) -> String {
    match spec.kind {
        ParamKind::Flag => "off or on".to_owned(),
        ParamKind::Choice => format!("menu: {}", spec.choices.join(", ")),
        ParamKind::Float | ParamKind::Count if spec.law.is_none() => {
            format!("stored {}", stored_range(spec))
        }
        ParamKind::Float | ParamKind::Count => {
            match (
                spec.physical(spec.stored_min),
                spec.physical(spec.stored_max),
            ) {
                (Ok(low), Ok(high)) if low.get() > high.get() => {
                    format!("{} to {}", shown(high), shown(low))
                }
                _ => format!(
                    "{} to {}",
                    bound(spec, spec.stored_min),
                    bound(spec, spec.stored_max)
                ),
            }
        }
    }
}

/// A range bound in the unit of the control. A bound the law cannot convert
/// is named: a level law gives no decibel value for a stored 0, which is
/// silence.
fn bound(spec: &ParamSpec, stored: f64) -> String {
    match (spec.physical(stored), &spec.law) {
        (Ok(value), _) => shown(value),
        (
            Err(_),
            Some(UnitLaw {
                law: Law::DbOfPower { .. },
                ..
            }),
        ) if stored <= 0.0 => "silence (-inf dB)".to_owned(),
        (Err(_), Some(law)) => format!(
            "stored {} (no {} value)",
            five(stored),
            law.unit.type_name()
        ),
        (Err(_), None) => format!("stored {}", five(stored)),
    }
}

fn stored_range(spec: &ParamSpec) -> String {
    format!("{} to {}", five(spec.stored_min), five(spec.stored_max))
}

/// A number at five significant digits, for reading.
fn five(value: f64) -> f64 {
    format!("{value:.4e}").parse().unwrap_or(value)
}

fn value(spec: &ParamSpec, stored: f64) -> String {
    match spec.kind {
        ParamKind::Flag => if stored < 0.5 { "off" } else { "on" }.to_owned(),
        ParamKind::Choice => {
            let mut at = spec.stored_min;
            for label in &spec.choices {
                if (at - stored).abs() < 0.5 {
                    return label.clone();
                }
                at += 1.0;
            }
            format!("stored {}", five(stored))
        }
        ParamKind::Float | ParamKind::Count => spec
            .physical(stored)
            .map_or_else(|_| format!("stored {}", five(stored)), shown),
    }
}

/// A physical value at five significant digits, for reading. The
/// registry keeps the exact value.
fn shown(value: Physical) -> String {
    Physical::new(value.kind(), five(value.get()))
        .ok()
        .unwrap_or(value)
        .to_string()
}

/// The default of a row; instances with other defaults are named.
fn defaults(row: &Row) -> String {
    let mut groups: Vec<(String, Vec<&str>)> = Vec::new();
    for (spec, id) in row.specs.iter().zip(
        row.instances
            .iter()
            .map(String::as_str)
            .chain(std::iter::repeat("")),
    ) {
        let text = value(spec, spec.default);
        match groups.iter_mut().find(|(have, _)| *have == text) {
            Some((_, ids)) => ids.push(id),
            None => groups.push((text, vec![id])),
        }
    }
    if groups.len() == 1 {
        return groups.remove(0).0;
    }
    groups
        .iter()
        .map(|(text, ids)| format!("{text} ({})", ids.join(", ")))
        .collect::<Vec<_>>()
        .join("; ")
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashSet;

    #[test]
    fn every_vital_key_lands_in_one_row_or_list() {
        let catalogue = Catalogue::of(Synth::Vital).unwrap();
        let registry = registry_for(Synth::Vital).unwrap();
        let mut seen = HashSet::new();
        for rows in catalogue.rows.values() {
            for row in rows {
                for spec in &row.specs {
                    assert!(seen.insert(spec.key.clone()), "{} twice", spec.key);
                }
            }
        }
        for key in &catalogue.legacy {
            assert!(seen.insert(key.clone()), "{key} twice");
        }
        assert_eq!(seen.len(), registry.iter().count());
        assert_eq!(catalogue.legacy.len(), 22);
    }

    #[test]
    fn a_pattern_splits_only_where_its_tags_differ() {
        let catalogue = Catalogue::of(Synth::Vital).unwrap();
        let cutoff: Vec<&Row> = catalogue.rows[&Some(Layer::Filter)]
            .iter()
            .filter(|row| row.pattern == "filter_N_cutoff")
            .collect();
        let tags: Vec<_> = cutoff
            .iter()
            .map(|row| (tag(&row.specs[0]), row.instances.clone()))
            .collect();
        assert_eq!(
            tags,
            [
                ("from facts", vec!["2".to_owned()]),
                ("measured", vec!["1".to_owned()])
            ]
        );
        let level = catalogue.rows[&Some(Layer::Oscillator)]
            .iter()
            .find(|row| row.pattern == "osc_N_level")
            .unwrap();
        assert_eq!(level.label, "Oscillator N Level");
        assert_eq!(level.instances, ["1", "2", "3"]);
    }

    #[test]
    fn files_stay_under_the_line_cap() {
        for (path, text) in generate().unwrap() {
            assert!(text.lines().count() <= 300, "{}", path.display());
            assert!(text.starts_with(HEADER));
        }
    }

    #[test]
    fn instances_keep_their_entries_when_sorted() {
        let registry = registry_for(Synth::Vital).unwrap();
        let spec = |key: &str, default: f64| {
            let mut spec = registry.get(key).unwrap().clone();
            spec.default = default;
            spec
        };
        // The registry order: `10` sorts before `2` as text.
        let mut row = Row {
            label: "Modulation N Amount".to_owned(),
            pattern: "modulation_N_amount".to_owned(),
            instances: vec!["1".to_owned(), "10".to_owned(), "2".to_owned()],
            specs: vec![
                spec("modulation_1_amount", 0.0),
                spec("modulation_10_amount", 0.5),
                spec("modulation_2_amount", 0.0),
            ],
        };
        sort_instances(&mut row);
        assert_eq!(row.instances, ["1", "2", "10"]);
        let keys: Vec<&str> = row.specs.iter().map(|spec| spec.key.as_str()).collect();
        assert_eq!(
            keys,
            [
                "modulation_1_amount",
                "modulation_2_amount",
                "modulation_10_amount"
            ]
        );
        assert_eq!(defaults(&row), "stored 0 (1, 2); stored 0.5 (10)");
    }

    #[test]
    fn a_bound_without_a_value_in_the_unit_is_named() {
        let registry = registry_for(Synth::Vital).unwrap();
        assert_eq!(
            range(registry.get("osc_1_level").unwrap()),
            "silence (-inf dB) to 0 dB"
        );
        let mut attack = registry.get("env_1_attack").unwrap().clone();
        attack.stored_min = -1.0;
        assert!(
            range(&attack).starts_with("stored -1 (no Seconds value) to "),
            "{}",
            range(&attack)
        );
    }

    #[test]
    fn every_vital_layer_text_names_its_keys_with_all_fields() {
        let catalogue = Catalogue::of(Synth::Vital).unwrap();
        for layer in Layer::ALL {
            let text = written(Synth::Vital, layer).unwrap();
            let problems = text_problems(layer, text, &catalogue.patterns(layer));
            assert!(problems.is_empty(), "{}", problems.join("\n"));
            assert!(!entries(text).is_empty(), "{layer} has no entries");
        }
    }

    #[test]
    fn a_missing_field_a_foreign_key_and_an_unnamed_pattern_are_named() {
        let text = "## Part\n\n### Glide\n- Keys: `portamento_time`, `osc_N_level`\n- Effect: no source\n\n## Next\n\n- Words: none\n";
        let problems = text_problems(Layer::Pitch, text, &["portamento_time", "legato"]);
        assert_eq!(
            problems,
            [
                "pitch: entry \"Glide\" lacks the field Words",
                "pitch: entry \"Glide\" names `osc_N_level`, which is no key pattern of this layer",
                "pitch: no entry names `legato`",
            ]
        );
    }

    #[test]
    fn a_vital_layer_file_opens_with_contents_of_both_parts() {
        let files = generate().unwrap();
        for layer in Layer::ALL {
            let text = &files[&Path::new(REFERENCE)
                .join("vital")
                .join(format!("{layer}.md"))];
            let headings: Vec<&str> = text
                .lines()
                .filter(|line| line.starts_with("## "))
                .collect();
            assert_eq!(headings.first(), Some(&"## Contents"), "{layer}");
            let written = written(Synth::Vital, layer).unwrap();
            for heading in written.lines().filter_map(|line| line.strip_prefix("## ")) {
                assert!(
                    text.contains(&format!("- [{heading}](#{})", anchor(heading))),
                    "{layer}: {heading}"
                );
            }
            let mut unique = headings.clone();
            unique.sort_unstable();
            unique.dedup();
            assert_eq!(unique.len(), headings.len(), "{layer} repeats a heading");
        }
    }

    #[test]
    fn defaults_name_the_instances_that_differ() {
        let catalogue = Catalogue::of(Synth::Vital).unwrap();
        let on = catalogue.rows[&Some(Layer::Oscillator)]
            .iter()
            .find(|row| row.pattern == "osc_N_on")
            .unwrap();
        assert_eq!(defaults(on), "on (1); off (2, 3)");
    }
}
